from typing import List

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        S = [0] * (n + 1)
        s_val = 0
        for i in range(n):
            s_val += nums[i]
            S[i+1] = s_val

        dp = [0] * (n + 1)
        INF = 10**15

        for j in range(1, k + 1):
            new_dp = [-INF] * (n + 1)
            max_val = -INF
            start = j * m

            for i in range(start, n + 1):
                val = dp[i-m] - S[i-m]
                if val > max_val:
                    max_val = val

                curr = S[i] + max_val

                if i > start:
                    prev = new_dp[i-1]
                    if prev > curr:
                        curr = prev

                new_dp[i] = curr

            dp = new_dp

        return dp[n]
